// Парсим Telegram widget страницу (t.me/s/channel)
// ИСПРАВЛЕНО: улучшенное извлечение фото
const input = $input.first().json;

if (input.error || !input.data) {
  console.log('Ошибка загрузки Telegram:', input.error || 'пустой ответ');
  return [];
}

const html = input.data;
const items = [];
const sourceData = $input.first().json || {};

// Разбиваем HTML на отдельные посты
const postBlocks = html.split('tgme_widget_message_wrap').slice(1);

for (let i = 0; i < Math.min(postBlocks.length, 10); i++) {
  const postHtml = postBlocks[i];

  // ID поста
  const postIdMatch = postHtml.match(/data-post="([^"]+)"/i);
  if (!postIdMatch) continue;
  const postId = postIdMatch[1];

  // Текст поста
  const textMatch = postHtml.match(/tgme_widget_message_text[^>]*>([\s\S]*?)<\/div>/i);
  let text = textMatch ? textMatch[1] : '';

  text = text
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]*>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .trim();

  // Дата поста
  const dateMatch = postHtml.match(/datetime="([^"]+)"/i);
  const pubDate = dateMatch ? dateMatch[1] : new Date().toISOString();

  // === ФОТО - множественные методы поиска ===
  let mediaUrl = '';

  // Метод 1: ищем в tgme_widget_message_photo_wrap
  const photoWrapMatch = postHtml.match(/tgme_widget_message_photo_wrap[^>]*style="[^"]*background-image:\s*url\(['"]?([^'"\)]+)['"]?\)/i);
  if (photoWrapMatch) {
    mediaUrl = photoWrapMatch[1];
  }

  // Метод 2: любой background-image с cdn telegram
  if (!mediaUrl) {
    const bgMatch = postHtml.match(/background-image:\s*url\(['"]?(https:\/\/cdn[^'"\)\s]+)['"]?\)/i);
    if (bgMatch) mediaUrl = bgMatch[1];
  }

  // Метод 3: тег img внутри photo блока
  if (!mediaUrl) {
    const imgInPhoto = postHtml.match(/tgme_widget_message_photo[^>]*>[\s\S]*?<img[^>]*src="([^"]+)"/i);
    if (imgInPhoto) mediaUrl = imgInPhoto[1];
  }

  // Метод 4: любой img с cdn4.telegram
  if (!mediaUrl) {
    const cdnImg = postHtml.match(/<img[^>]*src="(https:\/\/cdn[45]?\.telegram[^"]+)"/i);
    if (cdnImg) mediaUrl = cdnImg[1];
  }

  // Метод 5: data-src для lazy loading
  if (!mediaUrl) {
    const dataSrc = postHtml.match(/data-src="(https:\/\/cdn[^"]+)"/i);
    if (dataSrc) mediaUrl = dataSrc[1];
  }

  // Метод 6: просто ищем URL картинки телеграма
  if (!mediaUrl) {
    const anyTgImg = postHtml.match(/https:\/\/cdn[45]?\.telegram\.org\/file\/[^"'\s\)]+/i);
    if (anyTgImg) mediaUrl = anyTgImg[0];
  }

  const link = `https://t.me/${postId}`;

  if (text && text.length > 30) {
    items.push({
      title: text.substring(0, 100).replace(/\n/g, ' '),
      link,
      description: text.substring(0, 1500),
      pubDate,
      mediaUrl,
      source_id: sourceData.id || 'telegram',
      source_name: sourceData.name || 'Telegram',
      source_type: 'telegram'
    });
  }
}

console.log(`Telegram: найдено ${items.length} постов, с фото: ${items.filter(i => i.mediaUrl).length}`);
return items.map(item => ({ json: item }));

// Парсим RSS XML
const input = $input.first().json;

if (input.error || !input.data) {
  console.log('Ошибка загрузки RSS:', input.error || 'пустой ответ');
  return [];
}

const xml = input.data;
const items = [];
const sourceData = $input.first().json || {};

const itemRegex = /<item[^>]*>([\s\S]*?)<\/item>/gi;
let match;

while ((match = itemRegex.exec(xml)) !== null && items.length < 10) {
  const itemXml = match[1];

  const getTag = (tag) => {
    const regex = new RegExp(`<${tag}[^>]*><!\\[CDATA\\[([\\s\\S]*?)\\]\\]><\\/${tag}>|<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i');
    const m = itemXml.match(regex);
    return m ? (m[1] || m[2] || '').trim() : '';
  };

  const title = getTag('title');
  const link = getTag('link');
  let description = getTag('description');
  const pubDate = getTag('pubDate');

  description = description
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]*>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .trim();

  let mediaUrl = '';

  const enclosureMatch = itemXml.match(/<enclosure[^>]*url=["']([^"']+)["'][^>]*>/i);
  if (enclosureMatch) mediaUrl = enclosureMatch[1];

  if (!mediaUrl) {
    const mediaMatch = itemXml.match(/<media:content[^>]*url=["']([^"']+)["'][^>]*>/i);
    if (mediaMatch) mediaUrl = mediaMatch[1];
  }

  if (!mediaUrl) {
    const imgMatch = itemXml.match(/<image[^>]*>([\s\S]*?)<\/image>/i);
    if (imgMatch) {
      const urlMatch = imgMatch[1].match(/<url>([^<]+)<\/url>/i);
      if (urlMatch) mediaUrl = urlMatch[1];
    }
  }

  if (title && !title.includes('Trial has Expired') && !title.includes('Action required')) {
    items.push({
      title,
      link,
      description: description.substring(0, 1500),
      pubDate,
      mediaUrl,
      source_id: sourceData.id || 'rss',
      source_name: sourceData.name || 'RSS',
      source_type: 'rss'
    });
  }
}

console.log(`RSS: найдено ${items.length} постов`);
return items.map(item => ({ json: item }));

// Парсим VK публичную страницу
const input = $input.first().json;

if (input.error || !input.data) {
  console.log('Ошибка загрузки VK:', input.error || 'пустой ответ');
  return [];
}

const html = input.data;
const items = [];
const sourceData = $input.first().json || {};

const textBlocks = html.match(/<div[^>]*class="[^"]*wall_post_text[^"]*"[^>]*>([\s\S]*?)<\/div>/gi) || [];

for (let i = 0; i < Math.min(textBlocks.length, 10); i++) {
  const block = textBlocks[i];
  let text = block
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]*>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .trim();

  if (text && text.length > 30) {
    items.push({
      title: text.substring(0, 100).replace(/\n/g, ' '),
      link: sourceData.url || 'https://vk.com',
      description: text.substring(0, 1500),
      pubDate: new Date().toISOString(),
      mediaUrl: '',
      source_id: sourceData.id || 'vk',
      source_name: sourceData.name || 'VK',
      source_type: 'vk'
    });
  }
}

console.log(`VK: найдено ${items.length} постов`);
return items.map(item => ({ json: item }));

// Создаём hash + фильтрация рекламы + ФИЛЬТР ПРОШЕДШИХ ДАТ
const crypto = require('crypto');

const items = $input.all();
const result = [];
const now = new Date();

const stopWords = ['ERID', 'erid', 'реклама', 'Реклама', 'РЕКЛАМА', 'партнёрский', 'партнерский', 'промокод', '#реклама', '#ad', 'спонсор'];

// Месяцы для парсинга дат
const months = {
  'января': 0, 'февраля': 1, 'марта': 2, 'апреля': 3, 'мая': 4, 'июня': 5,
  'июля': 6, 'августа': 7, 'сентября': 8, 'октября': 9, 'ноября': 10, 'декабря': 11
};

// Проверка на прошедшую дату события
function hasPastEventDate(text) {
  if (!text) return false;

  // Паттерн: "15 октября", "1-5 ноября", "с 10 по 15 декабря"
  const datePattern = /(\d{1,2})(?:\s*[-–]\s*\d{1,2})?\s+(января|февраля|марта|апреля|мая|июня|июля|августа|сентября|октября|ноября|декабря)/gi;

  let match;
  while ((match = datePattern.exec(text)) !== null) {
    const day = parseInt(match[1]);
    const monthName = match[2].toLowerCase();
    const month = months[monthName];

    if (month !== undefined) {
      let year = now.getFullYear();
      const eventDate = new Date(year, month, day, 23, 59, 59);

      // Если дата уже прошла более чем на 1 день
      const diffDays = (now - eventDate) / (1000 * 60 * 60 * 24);
      if (diffDays > 1) {
        console.log(`ПРОПУСК прошедшего события (${day} ${monthName}): ${text.substring(0, 60)}...`);
        return true;
      }
    }
  }
  return false;
}

for (const item of items) {
  const data = item.json;
  const text = (data.title || '') + ' ' + (data.description || '');

  // Проверяем на стоп-слова (реклама)
  const hasStopWord = stopWords.some(word => text.includes(word));
  if (hasStopWord) {
    console.log('Пропускаем рекламу:', data.title?.substring(0, 50));
    continue;
  }

  // НОВОЕ: Проверяем на прошедшие события
  if (hasPastEventDate(text)) {
    continue;
  }

  // Проверяем свежесть поста (не старше 14 дней)
  if (data.pubDate) {
    const postDate = new Date(data.pubDate);
    const ageDays = (now - postDate) / (1000 * 60 * 60 * 24);
    if (ageDays > 14) {
      console.log(`Старый пост (${Math.floor(ageDays)} дней):`, data.title?.substring(0, 50));
      continue;
    }
  }

  // ИСПРАВЛЕНО: Hash только по заголовку (без pubDate) для ловли дублей
  const hashInput = (data.title || '').toLowerCase().replace(/[^а-яёa-z0-9]/gi, '').substring(0, 100);
  const hash = crypto.createHash('md5').update(hashInput).digest('hex').substring(0, 12);

  result.push({
    json: {
      ...data,
      content_hash: hash
    }
  });
}

console.log(`После фильтрации: ${result.length} постов`);
return result;

// Убираем дубли + семантическая проверка похожих событий
const news = $('Фильтруем и создаём hash').all();
const published = $('Читаем опубликованные').all();

// Нормализация текста для сравнения
function normalize(text) {
  if (!text) return '';
  return text.toLowerCase()
    .replace(/[^а-яёa-z0-9\s]/gi, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// Извлечение ключевых слов события
function extractKeywords(text) {
  if (!text) return [];
  const normalized = normalize(text);
  const stopWords = ['в', 'на', 'и', 'с', 'по', 'для', 'от', 'до', 'из', 'за', 'о', 'об', 'при', 'что', 'как', 'это', 'все', 'вас', 'вам', 'мы', 'вы', 'не', 'да', 'нет', 'будет', 'где', 'вход', 'бесплатно'];
  return normalized.split(' ').filter(w => w.length > 3 && !stopWords.includes(w)).slice(0, 8);
}

// Проверка похожести событий
function isSimilarEvent(title1, title2) {
  const kw1 = extractKeywords(title1);
  const kw2 = extractKeywords(title2);
  if (kw1.length < 2 || kw2.length < 2) return false;
  const common = kw1.filter(w => kw2.some(w2 => w2.includes(w) || w.includes(w2)));
  return common.length >= 3; // 3+ общих слов = похожее событие
}

const publishedHashes = new Set(
  published.map(p => p.json.content_hash).filter(Boolean)
);

const publishedTitles = published.map(p => p.json.title).filter(Boolean);

console.log(`Опубликовано ранее: ${publishedHashes.size} постов`);

const newItems = news.filter(item => {
  // Проверка по хешу
  if (publishedHashes.has(item.json.content_hash)) {
    console.log('Дубль по хешу:', item.json.title?.substring(0, 50));
    return false;
  }

  // Семантическая проверка
  const similar = publishedTitles.find(pt => isSimilarEvent(item.json.title, pt));
  if (similar) {
    console.log('Похожее событие:', item.json.title?.substring(0, 40), '~', similar?.substring(0, 40));
    return false;
  }

  return true;
});

console.log(`Новых постов: ${newItems.length}`);

if (newItems.length === 0) {
  return [];
}

// Сортируем по дате и берём 1
newItems.sort((a, b) => {
  const dateA = new Date(a.json.pubDate || 0);
  const dateB = new Date(b.json.pubDate || 0);
  return dateB - dateA;
});

return [newItems[0]];

// Собираем данные для LLM
const news = $('Убираем дубли').first().json;
const settingsRows = $('Читаем настройки').all();

const settings = {};
for (const row of settingsRows) {
  settings[row.json.key] = row.json.value;
}

// ИСПРАВЛЕННЫЙ ПРОМПТ - запрет галлюцинаций
const defaultPrompt = `Ты - редактор Telegram-канала о бесплатных событиях в Петербурге.

КРИТИЧЕСКИ ВАЖНО - СТРОГИЕ ПРАВИЛА:
1. НИКОГДА не выдумывай информацию!
2. Если в тексте НЕТ точной даты - пиши "Уточняйте на месте"
3. Если в тексте НЕТ адреса - пиши "Уточняйте место проведения"
4. Бери ТОЛЬКО факты из исходного текста!
5. НЕ добавляй детали от себя!

ФОРМАТ ПОСТА:
[Эмодзи категории] Название события

📅 [Дата из текста ИЛИ "Уточняйте на месте"]
📍 [Адрес из текста ИЛИ "Уточняйте место проведения"]
💰 БЕСПЛАТНО

[2-3 предложения из источника]

ℹ️ [Регистрация/возраст если указано]

Эмодзи категорий: 🎭 культура, 🎨 выставки, 🎵 концерты, 🏃 спорт, 👨‍👩‍👧‍👦 дети, 🎉 фестивали, 📚 лекции

Максимум 700 символов. Убери HTML-теги и рекламные ссылки.`;

const prompt = settings.prompt || defaultPrompt;
const maxLength = settings.max_post_length || 700;

const userMessage = `${prompt}

---
ИСХОДНЫЙ ТЕКСТ:

${news.description}

Источник: ${news.source_name}
---

Выдай ТОЛЬКО текст поста.`;

return [{
  json: {
    ...news,
    settings,
    userMessage,
    maxLength
  }
}];

// Извлекаем текст поста из ответа LLM
const input = $input.first().json;
const originalData = $('Готовим промпт').first().json;

let postText = '';

if (input.message && input.message.content) {
  postText = input.message.content;
} else if (input.text) {
  postText = input.text;
} else if (input.content) {
  postText = input.content;
} else if (typeof input === 'string') {
  postText = input;
}

postText = postText
  .replace(/```[\s\S]*?```/g, '')
  .replace(/^```\w*\n?/gm, '')
  .replace(/```$/gm, '')
  .trim();

const maxLength = originalData.maxLength || 700;
if (postText.length > maxLength + 100) {
  postText = postText.substring(0, maxLength) + '...';
}

console.log(`Пост готов: ${postText.length} символов, фото: ${originalData.mediaUrl ? 'да' : 'нет'}`);

return [{
  json: {
    post_text: postText,
    media_url: originalData.mediaUrl || '',
    content_hash: originalData.content_hash,
    title: originalData.title,
    link: originalData.link,
    source_id: originalData.source_id,
    source_name: originalData.source_name,
    settings: originalData.settings
  }
}];

// Fallback если фото не загрузилось
const input = $input.first().json;
const originalData = $('Извлекаем пост').first().json;

if (input.error || input.ok === false) {
  console.log('Ошибка отправки фото, отправим текстом');
  return [{ json: originalData }];
}

return [{ json: { ...originalData, sent_with_photo: true } }];
